import { timingSafeEqual } from 'crypto';
import type { RequestHandler } from 'express';
import { isLoopbackAddress } from '../utils/loopback';
import {
  EDITOR_ACCESS_TOKEN_HEADER,
  isEditorApiPath,
} from '../utils/editorAccess';

export const authenticateEditor =
  (token: string): RequestHandler =>
  (req, res, next) => {
    const host = `127.0.0.1:${req.socket.localPort}`;
    if (
      !isLoopbackAddress(req.socket.remoteAddress) ||
      req.headers.host !== host ||
      (req.headers.origin !== undefined &&
        req.headers.origin !== `http://${host}`)
    ) {
      res
        .status(403)
        .json({ error: 'Editor access requires the local editor origin.' });
      return;
    }
    const supplied = req.get(EDITOR_ACCESS_TOKEN_HEADER);
    if (
      !token ||
      !supplied ||
      Buffer.byteLength(supplied) !== Buffer.byteLength(token) ||
      !timingSafeEqual(Buffer.from(supplied), Buffer.from(token))
    ) {
      res.status(401).json({
        error: 'Open Rivet from its local launch link to access this editor.',
      });
      return;
    }
    next();
  };

export const authenticateEditorApi = (token: string): RequestHandler => {
  const authenticate = authenticateEditor(token);
  return (req, res, next) => {
    if (isEditorApiPath(req.path, req.method)) {
      authenticate(req, res, next);
      return;
    }
    next();
  };
};
